import{_ as t,o,c as a,a2 as r}from"./chunks/framework.Boholvbs.js";const u=JSON.parse('{"title":"Desktop app","description":"The PrioriCode desktop app — an Electron shell around the full agent: channels, sidecar server, auto-update, WSL, and how it stores state.","frontmatter":{"title":"Desktop app","description":"The PrioriCode desktop app — an Electron shell around the full agent: channels, sidecar server, auto-update, WSL, and how it stores state."},"headers":[],"relativePath":"platforms/desktop.md","filePath":"platforms/desktop.md"}'),i={name:"platforms/desktop.md"};function s(d,e,n,l,h,p){return o(),a("div",null,[...e[0]||(e[0]=[r('<p>The desktop app puts the same engine behind window chrome: the web interface rendered in Electron, with a PrioriCode server process living next door. It&#39;s the phone-in-your-pocket of PrioriCode surfaces — one install, sessions everywhere.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Availability first: desktop builds are wired into the release pipeline but, as of this writing, release pages ship CLI binaries — the desktop app is marked <em>coming soon</em> in the project README. Check the <a href="https://github.com/Prioritech-Indonesia-Optima/prioricode/releases" target="_blank" rel="noreferrer">releases page</a> for <code>prioricode-desktop-…</code> artifacts; when they appear, this is what you&#39;re installing.</p></div><h2 id="what-it-actually-is" tabindex="-1">What it actually is <a class="header-anchor" href="#what-it-actually-is" aria-label="Permalink to &quot;What it actually is&quot;">​</a></h2><ul><li><strong>Electron</strong> shell rendering the same SolidJS app UI as <code>prioricode web</code> — sessions, prompts, settings — with native niceties: custom title bar (traffic lights on macOS, frameless-with-overlay on Windows), context menus, first-run onboarding, and a localized interface.</li><li><strong>Sidecar server</strong>: a real <code>prioricode</code> server process launched per window-session, with the embedded web UI disabled (the Electron renderer <em>is</em> the UI). Tools run locally, exactly as the CLI would.</li><li><strong>Deep link</strong>: <code>prioricode://</code> URLs can hand work to the app.</li></ul><h2 id="channels-dev-beta-prod" tabindex="-1">Channels: dev, beta, prod <a class="header-anchor" href="#channels-dev-beta-prod" aria-label="Permalink to &quot;Channels: dev, beta, prod&quot;">​</a></h2><p>Three identities side-by-side on one machine:</p><table tabindex="0"><thead><tr><th>Channel</th><th>App name</th><th>Bundle id</th><th>Database</th></tr></thead><tbody><tr><td>prod</td><td>PrioriCode</td><td><code>ai.prioricode.desktop</code></td><td>shared <code>prioricode.db</code></td></tr><tr><td>beta</td><td>PrioriCode Beta</td><td><code>ai.prioricode.desktop.beta</code></td><td>shared <code>prioricode.db</code></td></tr><tr><td>dev</td><td>PrioriCode Dev</td><td><code>ai.prioricode.desktop.dev</code></td><td>separate <code>prioricode-dev.db</code></td></tr></tbody></table><p>That last row is the interesting one: production and beta desktop builds share the CLI&#39;s database — sessions, projects, and coordination state carry between surfaces — while the dev channel is sandboxed to its own DB by design (see <a href="./../configure/files.html">config files</a> for the routing table).</p><h2 id="updates" tabindex="-1">Updates <a class="header-anchor" href="#updates" aria-label="Permalink to &quot;Updates&quot;">​</a></h2><p>Auto-update is packaged-only and dialog-driven: it notifies, you decide, download follows your choice. Beta/dev builds point at their own update feeds. If the app ever goes unresponsive there&#39;s a recovery flow with log export — no hunting for the log dir yourself.</p><h2 id="windows-wsl" tabindex="-1">Windows + WSL <a class="header-anchor" href="#windows-wsl" aria-label="Permalink to &quot;Windows + WSL&quot;">​</a></h2><p>On Windows the app can host sessions inside WSL distros: install the CLI within the distro (the installer one-liner) and the desktop app drives servers there, with the same attach-style connection as any remote server.</p><h2 id="relationship-to-prioricode-web" tabindex="-1">Relationship to <code>prioricode web</code> <a class="header-anchor" href="#relationship-to-prioricode-web" aria-label="Permalink to &quot;Relationship to `prioricode web`&quot;">​</a></h2><p>Same UI, different transport. The desktop wraps the app in Electron and talks to its own sidecar; <code>prioricode web</code> serves the same bundle over HTTP from a CLI machine. If you want sessions reachable from a phone or another computer, run the <strong>server</strong>, not the desktop.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./server.html">Server &amp; remote</a> — The browser-hosted sibling. <ul><li><a href="./../getting-started/install.html">Installation</a> — The CLI remains the supported install today.</li><li><a href="./../configure/files.html">Config files</a> — Channel-based DB routing explained.</li></ul></li></ul>',16)])])}const b=t(i,[["render",s]]);export{u as __pageData,b as default};
